-- Persistent world for kinxdred_home.
-- Additive only: new tables, functions, and one view. Do not edit this file
-- after it has been applied. Later changes are a new migration, with owner approval.
-- This does not alter, drop, or rewrite any pre-existing table.
-- Apply it by hand on the kinxdred_home project after review. Do not apply it to mirrored.

create table if not exists public.worlds (
  id text primary key check (id ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
  lock_token uuid,
  locked_at timestamptz
);

create table if not exists public.world_events (
  seq bigint generated always as identity,
  id text primary key,
  world_id text not null references public.worlds (id),
  tick integer,
  at timestamptz not null,
  who text not null,
  what text not null check (what in ('influence', 'agent_action', 'external', 'tick')),
  place text,
  target text,
  payload jsonb not null default '{}'::jsonb,
  source text not null,
  ip_hash text check (ip_hash is null or ip_hash ~ '^[0-9a-f]{64}$'),
  created_at timestamptz not null default now(),
  constraint world_events_seq_key unique (seq)
);

create index if not exists world_events_world_seq_idx
  on public.world_events (world_id, seq);

create index if not exists world_events_ip_created_idx
  on public.world_events (ip_hash, created_at)
  where ip_hash is not null;

create table if not exists public.world_snapshots (
  id bigint generated always as identity primary key,
  world_id text not null references public.worlds (id),
  tick integer not null check (tick >= 0),
  state jsonb not null,
  last_event_seq bigint not null default 0 check (last_event_seq >= 0),
  input_events jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now(),
  constraint world_snapshots_world_tick_key unique (world_id, tick)
);

create table if not exists public.world_source_runs (
  id bigint generated always as identity primary key,
  world_id text not null references public.worlds (id),
  source_id text not null,
  ran_at timestamptz not null default now(),
  ok boolean not null,
  appended integer not null default 0 check (appended >= 0),
  detail jsonb not null default '{}'::jsonb,
  constraint world_source_runs_detail_size check (octet_length(detail::text) <= 2000)
);

-- Pending versus applied is the snapshot cursor (last_event_seq), not a row update.
-- world_events and world_snapshots therefore reject UPDATE and DELETE.
create or replace function public.world_reject_mutation()
returns trigger
language plpgsql
as $$
begin
  raise exception 'append-only' using errcode = '55000';
end;
$$;

drop trigger if exists world_events_no_update on public.world_events;
create trigger world_events_no_update
  before update or delete on public.world_events
  for each row execute function public.world_reject_mutation();

drop trigger if exists world_snapshots_no_update on public.world_snapshots;
create trigger world_snapshots_no_update
  before update or delete on public.world_snapshots
  for each row execute function public.world_reject_mutation();

create or replace function public.world_append_event(
  p_id text,
  p_world_id text,
  p_at timestamptz,
  p_who text,
  p_what text,
  p_place text,
  p_target text,
  p_payload jsonb,
  p_source text,
  p_ip_hash text,
  p_limit integer default 30,
  p_window_seconds integer default 60
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
  v_limit integer := p_limit;
  v_window integer := p_window_seconds;
begin
  if p_world_id is null or p_world_id !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' then
    return jsonb_build_object('ok', false, 'error', 'bad_event');
  end if;
  if p_id is null or length(p_id) < 1 or length(p_id) > 180 then
    return jsonb_build_object('ok', false, 'error', 'bad_event');
  end if;
  if p_who is null or length(p_who) < 1 or length(p_who) > 200 then
    return jsonb_build_object('ok', false, 'error', 'bad_event');
  end if;
  if p_what not in ('influence', 'agent_action', 'external') then
    return jsonb_build_object('ok', false, 'error', 'bad_event');
  end if;
  if p_source is null or length(p_source) < 1 or length(p_source) > 80 then
    return jsonb_build_object('ok', false, 'error', 'bad_event');
  end if;
  if p_ip_hash is not null and p_ip_hash !~ '^[0-9a-f]{64}$' then
    return jsonb_build_object('ok', false, 'error', 'bad_event');
  end if;
  if p_payload is not null and octet_length(p_payload::text) > 4096 then
    return jsonb_build_object('ok', false, 'error', 'bad_event');
  end if;

  insert into public.worlds (id) values (p_world_id) on conflict (id) do nothing;

  if p_ip_hash is not null then
    if v_limit is null or v_limit < 1 or v_limit > 100 then
      v_limit := 30;
    end if;
    if v_window is null or v_window < 1 or v_window > 3600 then
      v_window := 60;
    end if;
    perform pg_advisory_xact_lock(hashtext(p_ip_hash));
    select count(*) into v_count
      from public.world_events
      where ip_hash = p_ip_hash
        and created_at > now() - make_interval(secs => v_window);
    if v_count >= v_limit then
      return jsonb_build_object('ok', false, 'error', 'rate_limited');
    end if;
  end if;

  insert into public.world_events (
    id, world_id, tick, at, who, what, place, target, payload, source, ip_hash
  ) values (
    p_id,
    p_world_id,
    null,
    p_at,
    p_who,
    p_what,
    p_place,
    p_target,
    coalesce(p_payload, '{}'::jsonb),
    p_source,
    p_ip_hash
  )
  on conflict (id) do nothing;

  if not found then
    return jsonb_build_object('ok', true, 'duplicate', true);
  end if;
  return jsonb_build_object('ok', true, 'duplicate', false);
end;
$$;

create or replace function public.world_begin_tick(p_world_id text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_token uuid := gen_random_uuid();
  v_snap public.world_snapshots%rowtype;
  v_events jsonb;
begin
  if p_world_id is null or p_world_id !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' then
    return jsonb_build_object('acquired', false, 'error', 'bad_world');
  end if;

  insert into public.worlds (id) values (p_world_id) on conflict (id) do nothing;

  update public.worlds
    set lock_token = v_token,
        locked_at = now()
    where id = p_world_id
      and (lock_token is null or locked_at < now() - interval '30 seconds');

  if not found then
    return jsonb_build_object('acquired', false);
  end if;

  select * into v_snap
    from public.world_snapshots
    where world_id = p_world_id
    order by tick desc
    limit 1;

  select coalesce(jsonb_agg(jsonb_build_object(
    'seq', e.seq,
    'id', e.id,
    'worldId', e.world_id,
    'tick', null,
    'at', e.at,
    'who', e.who,
    'what', e.what,
    'where', e.place,
    'target', e.target,
    'payload', e.payload,
    'source', e.source
  ) order by e.seq), '[]'::jsonb)
  into v_events
  from (
    select *
    from public.world_events
    where world_id = p_world_id
      and what <> 'tick'
      and seq > coalesce(v_snap.last_event_seq, 0)
    order by seq
    limit 500
  ) e;

  return jsonb_build_object(
    'acquired', true,
    'token', v_token,
    'snapshot', v_snap.state,
    'tick', coalesce(v_snap.tick, 0),
    'lastEventSeq', coalesce(v_snap.last_event_seq, 0),
    'events', v_events
  );
end;
$$;

create or replace function public.world_commit_tick(
  p_world_id text,
  p_token uuid,
  p_before jsonb,
  p_tick integer,
  p_state jsonb,
  p_last_event_seq bigint,
  p_input_events jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_locked uuid;
  v_latest_tick integer;
  v_latest_seq bigint;
begin
  select lock_token into v_locked
    from public.worlds
    where id = p_world_id
    for update;

  if v_locked is distinct from p_token then
    return jsonb_build_object('ok', false, 'error', 'lost_lock');
  end if;

  if p_state is null then
    update public.worlds
      set lock_token = null, locked_at = null
      where id = p_world_id and lock_token = p_token;
    return jsonb_build_object('ok', true, 'aborted', true);
  end if;

  if jsonb_typeof(p_state) <> 'object'
    or jsonb_typeof(p_input_events) <> 'array'
    or p_tick is null
    or p_last_event_seq is null
    or octet_length(p_state::text) > 800000
    or octet_length(p_input_events::text) > 500000
  then
    update public.worlds
      set lock_token = null, locked_at = null
      where id = p_world_id and lock_token = p_token;
    return jsonb_build_object('ok', false, 'error', 'bad_state');
  end if;

  select tick, last_event_seq into v_latest_tick, v_latest_seq
    from public.world_snapshots
    where world_id = p_world_id
    order by tick desc
    limit 1;

  if v_latest_tick is null then
    if p_before is null or jsonb_typeof(p_before) <> 'object' then
      update public.worlds
        set lock_token = null, locked_at = null
        where id = p_world_id and lock_token = p_token;
      return jsonb_build_object('ok', false, 'error', 'bad_state');
    end if;
    insert into public.world_snapshots (world_id, tick, state, last_event_seq, input_events)
    values (p_world_id, 0, p_before, 0, '[]'::jsonb);
    v_latest_tick := 0;
    v_latest_seq := 0;
  end if;

  if p_tick <> v_latest_tick + 1 or p_last_event_seq < v_latest_seq then
    update public.worlds
      set lock_token = null, locked_at = null
      where id = p_world_id and lock_token = p_token;
    return jsonb_build_object('ok', false, 'error', 'tick_conflict');
  end if;

  insert into public.world_snapshots (world_id, tick, state, last_event_seq, input_events)
  values (p_world_id, p_tick, p_state, p_last_event_seq, p_input_events);

  update public.worlds
    set lock_token = null, locked_at = null
    where id = p_world_id and lock_token = p_token;

  return jsonb_build_object('ok', true, 'tick', p_tick);
exception
  when unique_violation then
    update public.worlds
      set lock_token = null, locked_at = null
      where id = p_world_id and lock_token = p_token;
    return jsonb_build_object('ok', false, 'error', 'tick_conflict');
end;
$$;

create or replace view public.world_transitions as
select
  next.world_id,
  next.tick,
  prev.state as state,
  next.input_events as events,
  next.state as next_state
from public.world_snapshots next
join public.world_snapshots prev
  on prev.world_id = next.world_id
 and prev.tick = next.tick - 1;

insert into public.worlds (id) values ('kinxdred') on conflict (id) do nothing;

alter table public.worlds enable row level security;
alter table public.world_events enable row level security;
alter table public.world_snapshots enable row level security;
alter table public.world_source_runs enable row level security;

-- No policies. anon and authenticated have no grants. The server uses the service key.
do $revoke$
declare
  obj text;
  role_name text;
  fn text;
begin
  foreach obj in array array[
    'public.worlds',
    'public.world_events',
    'public.world_snapshots',
    'public.world_source_runs',
    'public.world_transitions'
  ]
  loop
    execute format('revoke all on table %s from public', obj);
    foreach role_name in array array['anon', 'authenticated', 'service_role']
    loop
      if exists (select 1 from pg_roles where rolname = role_name) then
        execute format('revoke all on table %s from %I', obj, role_name);
      end if;
    end loop;
  end loop;

  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant select on table public.worlds to service_role;
    grant select on table public.world_events to service_role;
    grant select on table public.world_snapshots to service_role;
    grant select, insert on table public.world_source_runs to service_role;
    grant select on table public.world_transitions to service_role;
  end if;

  for fn in
    select p.oid::regprocedure::text
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname in (
        'world_append_event',
        'world_begin_tick',
        'world_commit_tick',
        'world_reject_mutation'
      )
  loop
    execute format('revoke all on function %s from public', fn);
    foreach role_name in array array['anon', 'authenticated']
    loop
      if exists (select 1 from pg_roles where rolname = role_name) then
        execute format('revoke all on function %s from %I', fn, role_name);
      end if;
    end loop;
    if exists (select 1 from pg_roles where rolname = 'service_role')
      and fn not like '%world_reject_mutation%'
    then
      execute format('grant execute on function %s to service_role', fn);
    end if;
  end loop;
end
$revoke$;

do $seq$
declare
  seq regclass;
  role_name text;
begin
  for seq in
    select s.oid::regclass
    from pg_class s
    join pg_namespace n on n.oid = s.relnamespace
    join pg_depend d on d.objid = s.oid and d.deptype = 'a'
    join pg_class t on t.oid = d.refobjid
    where s.relkind = 'S'
      and n.nspname = 'public'
      and t.relname in ('worlds', 'world_events', 'world_snapshots', 'world_source_runs')
  loop
    execute format('revoke all on sequence %s from public', seq);
    foreach role_name in array array['anon', 'authenticated']
    loop
      if exists (select 1 from pg_roles where rolname = role_name) then
        execute format('revoke all on sequence %s from %I', seq, role_name);
      end if;
    end loop;
  end loop;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant usage, select on sequence public.world_source_runs_id_seq to service_role;
  end if;
end
$seq$;

alter view public.world_transitions set (security_invoker = true);

comment on table public.world_events is
  'Append-only world events. Hashed visitor IPs only. Pending events are those with seq above the latest snapshot cursor.';
comment on table public.world_snapshots is
  'One row per tick, including tick 0 (the canon state before the first tick). input_events is the reducer input.';
comment on view public.world_transitions is
  'Training rows for a later world model: state, the events fed to step, and next_state.';
